export const KIT_ENGINE = "/* ---------- word clock: T('word', line, nth) = when that word is spoken ---------- */\nconst WORDS = window.__words, DUR = window.__dur;\nfunction T(needle, line, n = 0) {\n  const hits = WORDS.filter(w => w.line === line && w.w.toLowerCase().replace(/[^a-z0-9']/g, '') === needle.toLowerCase());\n  const h = hits[Math.min(n, hits.length - 1)]; if (!h) throw new Error('word not found: ' + needle + ' L' + line); return h.s;\n}\n\n/* ---------- ready-made beats (see the storyboard doc's recipe) ---------- */\nconst BEAT = {\n  // Camera: Kiko pops in the corner and says hi\n  hello(t, at, text = 'Hi!') { kiko(1640, 1075, .78, { mood: t < at + 2 ? 'happy' : 'talk', arm: 'up', t, s: pop(t, at), look: [-.6, -.3] }); bubble(1500, 470, text, { size: 40, tail: [60, 70], s: pop(t, at + .25) }); },\n  // Camera: Kiko holds up a sign (\"2 RULES\", \"3 STEPS\")\n  count(t, at, sign) { kiko(1640, 1075, .74, { mood: 'talk', sign, t, s: pop(t, at) }); },\n  // Camera: sticker words beside the head\n  stickers(t, list) { list.forEach(([at, until, label, fill, y]) => chip(1480, y, label, fill, { size: 54, rot: y % 2 ? .04 : -.05, s: pop(t, at) * (1 - p(t, until - .2, until)) })); },\n  // Camera: next-video card with Kiko and a guest\n  nextTime(t, at, title, sub, guest) {\n    kiko(1520, 1075, .7, { mood: 'cheer', arm: 'cheer', t, s: pop(t, at + .2) }); if (guest) guest(t, pop(t, at + .35));\n    const k = pop(t, at, .6); if (k <= 0) return;\n    ctx.save(); ctx.translate(1580, 330); ctx.rotate(.03); ctx.scale(k, k); sticker(() => rr(-300, -130, 600, 260, 24), C.paper, { sh: 10, lw: 6 });\n    txt('Next video', 0, -70, { size: 50, font: HAND, weight: 700 }); txt(title, 0, 20, { size: 66, color: C.gold, stroke: 10 }); txt(sub, 0, 88, { size: 40, font: HAND, weight: 700 }); ctx.restore();\n  },\n  // Cutaway: right way vs wrong way (draw functions receive (x, ok))\n  doDont(t, s0, label, tOk, tBad, draw) { paper(t, 0); tag(t, s0, label); draw(t, 560, true, pop(t, s0 + .1)); tick(830, 270, pop(t, tOk) * .8); draw(t, 1380, false, pop(t, tBad - .1)); cross(1660, 270, pop(t, tBad + .1) * .8); },\n  // Cutaway: three cards, too much / just right / too little — always end on just right\n  justRight(t, s0, label, tMuch, tLittle, tEnd, draw) {\n    paper(t, 1); tag(t, s0, label);\n    const cols = [[340, 'too much', C.sky, tMuch], [960, 'just right', C.mint, tEnd], [1580, 'too little', C.coral, tLittle]];\n    cols.forEach(([x, lab, col, at], i) => { const on = t >= at; sticker(() => rr(x - 290, 170, 580, 620, 24), on ? C.white : '#F3E2C6', { sh: on ? 7 : 0, lw: on ? 5 : 3 }); if (on) draw(t, x, i, pop(t, at)); chip(x, 830, lab, col, { size: 40, s: pop(t, s0 + .2 + i * .1) }); });\n  },\n};\n\n/* ---------- camera, captions, wipes ---------- */\nconst img = new Image();\nasync function cameraFrame(i, z) { img.src = `__FRAMES__/f_${String(i + 1).padStart(5, '0')}.jpg`; await img.decode(); const ax = 960, ay = 330; ctx.drawImage(img, ax - ax / z, ay - ay / z, W / z, H / z, 0, 0, W, H); }\nconst isKey = w => (window.__keywords || []).includes(w.toLowerCase().replace(/[^a-z0-9]/g, ''));\nconst GROUPS = (() => { const out = []; let cur = []; WORDS.forEach((w, i) => { cur.push(w); const nx = WORDS[i + 1]; if (w.brk || !nx || nx.line !== w.line) { out.push(cur); cur = []; } }); return out.flatMap(ph => { const n = Math.ceil(ph.length / 5), sz = Math.ceil(ph.length / n), r = []; for (let i = 0; i < ph.length; i += sz) r.push(ph.slice(i, i + sz)); return r; }); })();\nfunction captions(t) {\n  const gi = GROUPS.findIndex((g, i) => t >= g[0].s - .08 && t < Math.min((GROUPS[i + 1]?.[0].s ?? 1e9) - .08, g[g.length - 1].e + .5)); if (gi < 0) return;\n  const items = GROUPS[gi].map(w => { const k = isKey(w.w); const size = k ? 70 : 54; return { w, k, size, wd: measure(w.w, size) }; });\n  const sp = 24, total = items.reduce((a, b) => a + b.wd, 0) + sp * (items.length - 1); let x = W / 2 - total / 2;\n  items.forEach(it => { if (t >= it.w.s - .05) { const k = pop(t, it.w.s - .05, .28); ctx.save(); ctx.translate(x + it.wd / 2, 990); ctx.scale(k, k); ctx.rotate(it.k ? -.03 : 0);\n    txt(it.w.w, 0, 0, { size: it.size, color: it.k ? C.gold : C.white, stroke: it.k ? 11 : 8 });\n    if (it.k) { const u = p(t, it.w.s, it.w.e + .1); ctx.lineWidth = 6; ctx.strokeStyle = C.ink; ctx.lineCap = 'round'; ctx.beginPath(); for (let i = 0; i <= 30 * u; i++) { const q = i / 30; i ? ctx.lineTo(-it.wd / 2 + q * it.wd, 42 + Math.sin(q * 6) * 4) : ctx.moveTo(-it.wd / 2, 42); } ctx.stroke(); }\n    ctx.restore(); } x += it.wd + sp; });\n}\nfunction wipe(t, b, dir) {\n  const u = (t - (b - .3)) / .6; if (u <= 0 || u >= 1) return;\n  const cx = dir > 0 ? lerp(-1500, W + 1500, ease(u)) : lerp(W + 1500, -1500, ease(u)), half = 1250;\n  ctx.save(); ctx.beginPath(); ctx.moveTo(cx - half, -20);\n  for (let y = -20; y <= H + 20; y += 40) ctx.lineTo(cx + half + Math.sin(y / 90 + u * 6) * 50, y);\n  for (let y = H + 20; y >= -20; y -= 40) ctx.lineTo(cx - half + Math.sin(y / 80 + u * 5) * 50, y);\n  ctx.closePath(); ctx.fillStyle = C.gold; ctx.fill(); ctx.lineWidth = 8; ctx.strokeStyle = C.ink; ctx.stroke(); sparkle(cx, H / 2, 90, { rot: u * 4 }); ctx.restore();\n}\n\n";
